                  ></path>
                </svg>
              </el-tooltip>
            </template>
            <template slot-scope="{ row }">
              <span v-if="item.valueOption">{{
                setLabel(row[item.prop], item.valueOption)
              }}</span>
              <span v-else>{{ row[item.prop] }}</span>
            </template>
          </el-table-column>
          <!--					<el-table-column prop="name" label="姓名" width="180"></el-table-column>-->
        </template>
        <el-table-column :label="$t('common.operation')">
          <template slot-scope="{ row }">
            <el-button
              type="text"
              size="medium"
              @click.stop="$emit('edit', row)"
              >{{ $t('common.edit') }}</el-button
            >
            <el-button
              type="text"
              style="color: #fa5151"
              size="medium"
              @click.stop="onDelete(row)"
              >{{ $t('common.delete') }}</el-button
            >
          </template>
        </el-table-column>
      </el-table>
    </div>
    <!-- <Pagination
			:total="total"
			:current-page="paramsData.pageNum"
			:page-size="paramsData.pageSize"
			@current-change="handleCurrentChange" /> -->
  </div>
</template>

<script>
// import { Pagination } from "@/Financing/components";
import '../style/tooltip.less'
export default {
  name: 'ModuleTable',
  components: {
    // Pagination
  },
  props: {
    //模块名
    title: { type: String },
    /**
     * 标题icon类型，默认‘1’
     * 可选值 ‘2’
     */
    titleIconType: {
      type: String,
      default: '1',
    },
    placeholder: {
      type: String,
      default: '',
    },
    buttonText: {
      type: String,
    },
    //请求参数
    params: {
      type: Object,
      default: () => {},
    },
    //表格loading加载
    loading: {
      type: Boolean,
    },
    //是否禁用表格单元格点击
    cellClickDisabled: {
      type: Boolean,
    },
    //表格头
    tableColumn: {
      type: Array,
      default: () => [],
    },
    //表格数据
    tableData: {
      type: Array,
      default: () => [],
    },
    total: {
      type: Number,
      default: 0,
    },
  },
  data() {
    return {
      paramsData: {
        pageNum: 1,
        pageSize: 10,
        name: undefined,
        moduleId: undefined, //所属模块id
      },
    }
  },
  computed: {
    options() {
      return {
        typeOptions: [
          { label: this.$t('dataCenter.objectTypeValue'), value: 0 },
          { label: this.$t('dataCenter.collection'), value: 1 },
        ],
      }
    },
  },
  watch: {
    params: {
      handler(cur) {
        if (cur && Object.keys(cur).length) {
          const { page, size, ...newParams } = cur
          // console.log('newParams', newParams)
          Object.assign(this.paramsData, {
            pageNum: page || cur.pageNum,
            pageSize: size || cur.pageSize,
            ...newParams,
          })
        }
      },
      deep: true,
      immediate: true,
    },
  },
  methods: {
    setLabel(value, valueOption) {
      // console.log("value, valueOption", value, valueOption);
      const propData = this.options[valueOption].find(
        (item) => item.value == value
      )
      return propData ? propData.label : value
    },
    tableLightColor({ row, rowIndex }) {
      // console.log('this.paramsData.moduleId === row.id',this.paramsData.moduleId, row.id)
      return {
        'font-size': '14px',
        'font-weight': 400,
        color: 'rgba(0,0,0,0.85)',
        background:
          this.paramsData.moduleId === row.id
            ? 'RGBA(40, 136, 232, 0.1)'
            : '#FFFFFF',
      }
    },
    tableCellClick(row, column, cell, event) {
      if (this.cellClickDisabled) return
      this.paramsData.moduleId = row.id
      this.$emit('cellClick', row)
    },
    onDelete(row) {
      this.$confirm(
        this.$t('common.deleteConfirm'),
        this.$t('common.systemTip'),
        {
          confirmButtonText: this.$t('common.sure'),
          cancelButtonText: this.$t('common.cancel'),
          type: 'warning',
        }
      )
        .then(() => {
          this.$emit('delete', row)
        })
        .catch(() => {})
    },
    handleCurrentChange(num) {
      this.paramsData.pageNum = num
      this.$emit('currentChange', num)
    },
  },
}
</script>

